package com.example.payment.domain.order;

public final class Order {

    private final OrderId id;
    private final CustomerId customerId;
    private OrderStatus status;

    private Order(OrderId id, CustomerId customerId, OrderStatus status) {
        this.id = id;
        this.customerId = customerId;
        this.status = status;
    }

    public static Order place(OrderId id, CustomerId customerId) {
        return new Order(id, customerId, OrderStatus.PENDING);
    }

    public void cancel(CustomerId caller) {
        if (!customerId.equals(caller)) {
            throw new OrderNotOwnedException(id);
        }
        if (status != OrderStatus.PENDING) {
            throw new OrderNotPendingException(id);
        }
        status = OrderStatus.CANCELLED;
    }

    public OrderId id() {
        return id;
    }

    public CustomerId customerId() {
        return customerId;
    }

    public OrderStatus status() {
        return status;
    }
}
