package com.example.payment.app;

import com.example.payment.application.order.CancelOrder;
import com.example.payment.application.order.GetOrder;
import com.example.payment.application.order.OrderNotFoundException;
import com.example.payment.application.order.OrderViewModel;
import com.example.payment.domain.order.CustomerId;
import com.example.payment.domain.order.OrderId;
import com.example.payment.domain.order.OrderNotOwnedException;
import com.example.payment.domain.order.OrderNotPendingException;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
class OrderController {

    private final GetOrder getOrder;
    private final CancelOrder cancelOrder;

    OrderController(GetOrder getOrder, CancelOrder cancelOrder) {
        this.getOrder = getOrder;
        this.cancelOrder = cancelOrder;
    }

    @GetMapping("/orders/{id}")
    OrderViewModel get(@PathVariable String id, @RequestHeader("X-Customer-Id") String customerId) {
        return getOrder.handle(new OrderId(id), new CustomerId(customerId));
    }

    @PostMapping("/orders/{id}/cancel")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    void cancel(@PathVariable String id, @RequestHeader("X-Customer-Id") String customerId) {
        cancelOrder.handle(new OrderId(id), new CustomerId(customerId));
    }

    @ExceptionHandler({OrderNotFoundException.class, OrderNotOwnedException.class})
    @ResponseStatus(HttpStatus.NOT_FOUND)
    void notFound() {}

    @ExceptionHandler(OrderNotPendingException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    void notPending() {}
}
